    var th = document.createElement('button'); th.type = 'button'; th.className = 'secondary small'; th.setAttribute('aria-label', 'Toggle dark mode'); th.textContent = '◐'; th.onclick = function () { var d = document.documentElement.getAttribute('data-theme') === 'dark'; try { localStorage.setItem('careaxis_theme', d ? 'light' : 'dark'); } catch (e) { } applyTheme(); }; tr.insertBefore(th, av || tr.firstChild);
