    db.encounters.forEach(function (e) { if (e.patientId === pid) ev.push([e.at, '🩺', 'Consultation: ' + e.diagnosis, e.status]); });
    db.labOrders.forEach(function (l) { if (l.patientId === pid) ev.push([l.at, '🧪', 'Lab: ' + l.name, l.status]); });
    db.radOrders.forEach(function (r) { if (r.patientId === pid) ev.push([r.at, '🩻', 'Imaging: ' + r.name, r.status]); });
    db.prescriptions.forEach(function (r) { if (r.patientId === pid) ev.push([r.at, '💊', 'Prescription ' + r.id + ' (' + r.items.length + ' items)', r.status]); });
    db.admissions.forEach(function (a) { if (a.patientId === pid) ev.push([a.admittedAt, '🛏️', 'Admission · bed ' + a.bedId, a.status]); });
    db.invoices.forEach(function (i) { if (i.patientId === pid) ev.push([i.at, '🧾', 'Invoice ' + i.id + ' · ' + money(H.invTotal(i)), i.status]); });
    ev.sort(function (x, y) { return x[0] < y[0] ? 1 : -1; });
    var due = db.invoices.filter(function (i) { return i.patientId === pid && i.status !== 'Paid'; }).reduce(function (s, i) { return s + H.invTotal(i) - H.invPaid(i); }, 0);
    var m = UI.modal('Patient 360 · ' + p.name, '<div class="cx-p360"><div class="cx-phead">' + (p.photo ? '<img src="' + p.photo + '" alt="Photo of ' + esc(p.name) + '">' : '<div class="cx-ava">' + esc(p.name.charAt(0)) + '</div>') + '<div><h3>' + esc(p.name) + ' ' + (p.verified ? '<span class="badge green">Mobile verified</span>' : '<span class="badge orange">Unverified</span>') + '</h3><p class="muted">' + p.id + ' · ' + H.age(p.dob) + ' · ' + esc(p.gender) + ' · ' + esc(p.blood || '') + ' · 📱 ' + esc(p.mobile) + '</p><p>Payer: <b>' + esc(p.payer) + '</b> ' + esc(p.insurer || '') + ' · Allergies: <b class="' + (p.allergies && p.allergies !== 'None known' ? 'cx-alert' : '') + '">' + esc(p.allergies) + '</b> · Balance due: <b>' + money(due) + '</b></p></div></div><div class="formactions" style="justify-content:flex-start"><button type="button" class="small" data-x="book">Book appointment</button><button type="button" class="small secondary" data-x="walkin">Walk-in token</button><button type="button" class="small secondary" data-x="bills">Collect dues</button></div><h3>Health timeline</h3><ol class="cx-timeline">' + (ev.length ? ev.slice(0, 40).map(function (e) { return '<li><span class="cx-tl-ico" aria-hidden="true">' + e[1] + '</span><div><b>' + esc(e[2]) + '</b> ' + b(e[3]) + '<br><small class="muted">' + dt(e[0]) + '</small></div></li>'; }).join('') : '<li>No history yet</li>') + '</ol></div>', { wide: true });
