  P['operation-theatre/recovery'] = function () { content.innerHTML = setHead('Operation Theatre', 'Recovery (PACU)', 'Aldrete score ≥ 9 required to shift to ward.') + '<section class="panel" id="cxT"></section>'; tbl($('#cxT'), { title: 'Recovery', rows: function () { return H.db().otCases.filter(function (o) { return o.recovery; }); }, emptyText: 'No patients in recovery', cols: [C.pat, C.f('procedure', 'Procedure'), { h: 'Aldrete', get: function (r) { return r.recovery.aldrete + '/10'; } }, { h: 'Since', get: function (r) { return H.ago(r.recovery.at); } }, { h: 'Status', raw: true, get: function (r) { return b(r.recovery.status); } }], actions: function (r) { return r.recovery.status === 'In PACU' ? UI.btn('sc', 'Update score') + UI.btn('ward', 'Shift to ward', 'small') : ''; }, onAction: function (a, id) { var o = H.byId('otCases', id); if (a === 'sc') UI.form('Aldrete score', [{ name: 's', label: 'Score (0-10)', type: 'number', min: 0, max: 10, value: o.recovery.aldrete, required: true }], function (d) { o.recovery.aldrete = +d.s; H.save(); render(); }); else { if (o.recovery.aldrete < 9) throw new Error('Aldrete score must be ≥ 9 before shifting'); o.recovery.status = 'Shifted to ward'; H.log('Shifted from PACU', H.pname(o.patientId)); H.save(); render(); } } }); };
  P['operation-theatre/implants'] = function () { content.innerHTML = setHead('Operation Theatre', 'Implants register', 'Implants used per case (traceability) and implant stock.') + '<section class="panel" id="cxT"></section><section class="panel" id="cxS"></section>'; tbl($('#cxT'), { title: 'Cases with implants', rows: function () { return H.db().otCases.filter(function (o) { return o.implants && o.implants.length; }); }, cols: [C.pat, C.f('procedure', 'Procedure'), { h: 'Implants', get: function (r) { return r.implants.join(', '); } }, C.status] }); tbl($('#cxS'), { title: 'Implant stock', rows: function () { return H.db().items.filter(function (i) { return i.category === 'Implant'; }); }, cols: [C.f('name', 'Implant'), C.f('batch', 'Batch / lot'), C.f('stock', 'Stock'), { h: 'Price', get: function (r) { return money(r.price); } }] }); };

