  P['hr-payroll/attendance'] = function () { content.innerHTML = setHead('HR & Payroll', 'Attendance · ' + H.fmtDate(Date.now()), 'Biometric-style attendance for today. Mark manually where needed.') + '<section class="panel" id="cxT"></section>'; tbl($('#cxT'), { title: 'Attendance', rows: function () { var db = H.db(); return db.staff.map(function (s) { var a = db.attendance.filter(function (x) { return x.staffId === s.id && x.date === H.today(); })[0]; if (!a) { a = { id: H.uid('ATT'), staffId: s.id, date: H.today(), in: '', status: 'Absent' }; db.attendance.push(a); } a.name = s.name; a.role = s.role; return a; }); }, filters: ['Present', 'Late', 'Absent', 'Leave'], cols: [C.f('name', 'Employee'), C.f('role', 'Role'), C.f('in', 'In time'), C.status], actions: function (r) { return r.status === 'Absent' ? UI.btn('p', 'Mark present', 'small') : ''; }, onAction: function (a, id) { var x = H.byId('attendance', id); x.status = 'Present'; x.in = new Date().toTimeString().slice(0, 5); H.log('Attendance marked', x.name); H.save(); render(); } }); };
